&lt;li data-renderer-start-pos=&quot;2769&quot; data-local-id=&quot;46937c2f-d543-4fbd-b76c-3593c6541fb4&quot;&gt;&lt;span class=&quot;fabric-text-color-mark&quot; data-renderer-mark=&quot;true&quot; data-text-custom-color=&quot;#0747a6&quot;&gt;Proven experience with title testing, image testing, and structured experimentation&lt;/span&gt;&lt;/li&gt;
